<?php
// Jalankan sekali melalui browser: http://localhost/sembako_pos/setup.php
$host='localhost'; $user='root'; $pass=''; $db='sembako_pos';
try {
 $pdo=new PDO("mysql:host=$host;charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
 $pdo->exec("CREATE DATABASE IF NOT EXISTS `$db` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");
 $pdo->exec("USE `$db`");
 $pdo->exec("CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(60) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
 $pdo->exec("CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(80) UNIQUE NOT NULL,name VARCHAR(180) NOT NULL,category VARCHAR(100) DEFAULT 'Umum',unit VARCHAR(30) DEFAULT 'pcs',cost_price DECIMAL(14,2) NOT NULL DEFAULT 0,sell_price DECIMAL(14,2) NOT NULL DEFAULT 0,stock DECIMAL(14,3) NOT NULL DEFAULT 0,min_stock DECIMAL(14,3) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
 $pdo->exec("CREATE TABLE IF NOT EXISTS sales(id BIGINT AUTO_INCREMENT PRIMARY KEY,invoice VARCHAR(40) UNIQUE NOT NULL,subtotal DECIMAL(14,2) NOT NULL,total DECIMAL(14,2) NOT NULL,paid DECIMAL(14,2) NOT NULL,change_amount DECIMAL(14,2) NOT NULL,payment_method VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'Lunas',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
 $pdo->exec("CREATE TABLE IF NOT EXISTS sale_items(id BIGINT AUTO_INCREMENT PRIMARY KEY,sale_id BIGINT NOT NULL,product_id INT NOT NULL,product_name VARCHAR(180) NOT NULL,qty DECIMAL(14,3) NOT NULL,unit VARCHAR(30) NOT NULL,price DECIMAL(14,2) NOT NULL,cost_price DECIMAL(14,2) NOT NULL,line_total DECIMAL(14,2) NOT NULL,FOREIGN KEY(sale_id) REFERENCES sales(id),FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB");
 $pdo->exec("CREATE TABLE IF NOT EXISTS expenses(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,amount DECIMAL(14,2) NOT NULL,expense_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
 $stmt=$pdo->prepare('SELECT id FROM users WHERE username=?');$stmt->execute(['pemilik']);
 if(!$stmt->fetch()){$s=$pdo->prepare('INSERT INTO users(username,password) VALUES(?,?)');$s->execute(['pemilik',password_hash('GantiSaya123!',PASSWORD_DEFAULT)]);}
 $count=(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();
 if($count===0){$items=[['899001','Beras Premium','Sembako','kg',13000,16000,50,5],['899002','Minyak Goreng 1L','Sembako','botol',15000,18000,30,5],['899003','Gula Pasir','Sembako','kg',14000,17000,25,5],['899004','Mi Instan','Makanan','bungkus',2500,3000,100,10],['899005','Telur Ayam','Sembako','kg',26000,30000,15,3],['899006','Tepung Terigu','Sembako','kg',10000,12500,20,5],['899007','Kopi Sachet','Minuman','sachet',1000,1500,80,10],['899008','Sabun Mandi','Rumah Tangga','pcs',3500,5000,20,4]];$s=$pdo->prepare('INSERT INTO products(sku,name,category,unit,cost_price,sell_price,stock,min_stock) VALUES(?,?,?,?,?,?,?,?)');foreach($items as $it)$s->execute($it);}
 echo '<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Setup Sembako POS</title><body style="font:16px system-ui;max-width:650px;margin:10vh auto;padding:24px;background:#f5f7f6"><h1>Setup berhasil</h1><p>Database <b>sembako_pos</b> dan tabel sudah siap. Akun awal:</p><p>Username: <b>pemilik</b><br>Password: <b>GantiSaya123!</b></p><p><b>Segera ubah password setelah login.</b> Hapus atau ganti nama setup.php setelah selesai.</p><a href="index.php">Buka aplikasi →</a></body>';
